关系运算符重载
C++ 语言支持各种关系运算符（ &lt; 、 &gt; 、 ⇐ 、 &gt;= 、 == 等等），它们可用于比较 C++ 内置的数据类型。
您可以重载任何一个关系运算符，重载后的关系运算符可用于比较类的对象。
#include &lt;iostream&gt;
using namespace std;

class Distance
{
   private:
      int feet;             // 0 到无穷
      int inches;           // 0 到 12
   public:
      // 所需的构造函数
      Distance(){
         feet = 0;
         inches = 0;
      }
      Distance(int f, int i){
         feet = f;
         inches = i;
      }
      // 显示距离的方法
      void displayDistance()
      {
         cout &lt;&lt; &quot;F: &quot; &lt;&lt; feet &lt;&lt; &quot; I:&quot; &lt;&lt; inches &lt;&lt;endl;
      }
      // 重载负运算符（ - ）
      Distance operator- ()  
      {
         feet = -feet;
         inches = -inches;
         return Distance(feet, inches);
      }
      // 重载小于运算符（ &lt; ）
      bool operator &lt;(const Distance&amp; d)
      {
         if(feet &lt; d.feet)
         {
            return true;
         }
         if(feet == d.feet &amp;&amp; inches &lt; d.inches)
         {
            return true;
         }
         return false;
      }
};
int main()
{
   Distance D1(11, 10), D2(5, 11);

   if( D1 &lt; D2 )
   {
      cout &lt;&lt; &quot;D1 is less than D2 &quot; &lt;&lt; endl;
   }
   else
   {
      cout &lt;&lt; &quot;D2 is less than D1 &quot; &lt;&lt; endl;
   }
   return 0;
}
result:
D2 is less than D1
