	UARTCharPut(UART0_BASE, &#039;t&#039;);
	UARTCharPut(UART0_BASE, &#039;e&#039;);
	UARTCharPut(UART0_BASE, &#039;r&#039;);
	UARTCharPut(UART0_BASE, &#039; &#039;);
	UARTCharPut(UART0_BASE, &#039;T&#039;);
