uint8_t MPC_read(void)
{
	uint8_t temp;
	I2CStart();//开启I2C
	I2CSendByte(0X5F);//发送读
	I2CWaitAck();//等待
	temp=I2CReceiveByte();//接收数据
	I2CSendNotAck();//发送非应答
	I2CStop();//关闭I2C
	return temp;
}

void MPC_write(uint8_t data)
{
	I2CStart();//开启I2C
	I2CSendByte(0X5E);//发送写
	I2CWaitAck();//等待
	I2CSendByte(data);//发送数据
	I2CWaitAck();//等待
	I2CStop();//关闭I2C
}

void eeprom_write(uint8_t add,uint8_t data)
{
	I2CStart();//开启I2C
	I2CSendByte(0Xa0);//发送写
	I2CWaitAck();//等待
	I2CSendByte(1);//发送add
	I2CWaitAck();//等待
	I2CSendByte(data);//发送数据
	I2CWaitAck();//等待
	I2CStop();//关闭I2C
}

